async ({ workspace: { read, edit } }) => {
  const files = [".github/workflows/pi-assistant.yml", "docs/extensions.md", "docs/how-it-works.md"];
  const out: Record<string, number> = {};
  for (const f of files) {
    const r = await read(f, { format: "raw" });
    let c = r.content.replaceAll("github:cv/pit#v0.36.3", "github:cv/pit#v0.36.5");
    if (f === "docs/how-it-works.md") {
      c = c.replace('For a call with a label, such as a pit program with `// @pit: {"label": "..."}` as its first line, only the label.', "For a call with a `label` argument, only the label.")
           .replace("The arguments (a pit program without its `// @pit:` line, and long JSON values indented)", "The arguments (long JSON values indented)");
    }
    if (f === "docs/extensions.md") {
      c = c.replace("Give the tool an optional `present` field. pi-durable does not use it, so other hosts ignore it:", "Give the tool an optional `present` field. pi-durable does not use it, so other hosts ignore it. pit's `typescript` tool has one (pit 0.36.5 and later): the log shows the label of each program, its code, the functions it uses, and its result as text:");
    }
    out[f] = (c.match(/v0\.36\.5|pit 0\.36\.5 and later|`label` argument, only|long JSON values indented\)/g) ?? []).length;
    await edit(f, { revision: r.revision, changes: [{ kind: "replaceFile", content: c }] });
  }
  return out;
}
